import{_ as a,o as t,c as i,a3 as o}from"./chunks/framework.Dz5Q8p4s.js";const m=JSON.parse('{"title":"General Embodied AI","description":"","frontmatter":{"title":"General Embodied AI","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/embodied-ai-general.md","filePath":"en/tutorials/embodied-ai-general.md","lastUpdated":null}'),n={name:"en/tutorials/embodied-ai-general.md"};function l(r,e,s,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="general-embodied-ai-principles-·-methods-·-evaluation" tabindex="-1">General Embodied AI: Principles · Methods · Evaluation <a class="header-anchor" href="#general-embodied-ai-principles-·-methods-·-evaluation" aria-label="Permalink to &quot;General Embodied AI: Principles · Methods · Evaluation&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/embodied-ai-general">通用具身智能</a><strong>Coverage</strong>: June 2025 – July 2026, tracing back to RT-1/RT-2, OpenVLA, Diffusion Policy and π0. <strong>Papers</strong>: <a href="/notes/en/papers/#tut-embodied-ai-general">263 deep-read notes</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/embodied-ai-general">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>This is the panoramic entry point of the collection: the perception–cognition–action loop, what makes embodiment fundamentally harder than pure vision or language, and how the field&#39;s methods, data and benchmarks fit together.</p><p>Four gaps separate embodied AI from NLP and CV, and the tutorial keeps returning to them: the agent&#39;s own actions change its data distribution; supervision is expensive because it comes from real hardware; success is defined by task completion rather than by a differentiable loss; and evaluation cannot be reproduced from a static test set. It then offers a single &quot;capability dimensions&quot; framework for judging whether an embodied system is any good, and a stack diagram that places every method family discussed later.</p><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-how-to-use-this-tutorial" tabindex="-1">Chapter 0 — How to use this tutorial <a class="header-anchor" href="#chapter-0-—-how-to-use-this-tutorial" aria-label="Permalink to &quot;Chapter 0 — How to use this tutorial&quot;">​</a></h3><ul><li>0.1 What we are covering</li><li>0.2 Suggested reading paths</li><li>0.3 Scope</li></ul><h3 id="chapter-1-—-concepts-and-intuition" tabindex="-1">Chapter 1 — Concepts and intuition <a class="header-anchor" href="#chapter-1-—-concepts-and-intuition" aria-label="Permalink to &quot;Chapter 1 — Concepts and intuition&quot;">​</a></h3><ul><li>1.1 What &quot;embodied intelligence&quot; means</li><li>1.2 The perception–cognition–action loop in one diagram</li><li>1.3 Why embodiment is hard: four gaps relative to pure NLP/CV</li><li>1.4 Terminology at a glance</li><li>1.5 A unified &quot;capability dimensions&quot; framework</li><li>1.6 A panorama of the embodied AI technology stack</li></ul><h3 id="chapter-2-—-mathematical-principles-and-key-techniques" tabindex="-1">Chapter 2 — Mathematical principles and key techniques <a class="header-anchor" href="#chapter-2-—-mathematical-principles-and-key-techniques" aria-label="Permalink to &quot;Chapter 2 — Mathematical principles and key techniques&quot;">​</a></h3><ul><li>2.1 Formalisation: (PO)MDPs and robot control</li><li>2.2 Action representation — consistently underrated, consistently decisive</li><li>2.3 Imitation learning</li><li>2.4 Generative policies: diffusion and flow matching</li><li>2.5 Vision-Language-Action (VLA) architectures</li><li>2.6 Cross-embodiment learning and pretraining</li><li>2.7 Dual-system and hierarchical designs</li><li>2.8 World models for action</li><li>2.9 Embodied reasoning</li></ul><h3 id="chapter-3-—-task-taxonomy" tabindex="-1">Chapter 3 — Task taxonomy <a class="header-anchor" href="#chapter-3-—-task-taxonomy" aria-label="Permalink to &quot;Chapter 3 — Task taxonomy&quot;">​</a></h3><ul><li>3.1 Tabletop manipulation — the de facto benchmark task</li><li>3.2 Vision-language navigation (VLN)</li><li>3.3 Mobile manipulation</li><li>3.4 Humanoid, whole-body and loco-manipulation</li><li>3.5 Dexterous manipulation</li><li>3.6 Contact-rich, tactile and force control</li><li>3.7 Long-horizon tasks and planning</li><li>3.8 Other frontier task formats</li></ul><h3 id="chapter-4-—-data" tabindex="-1">Chapter 4 — Data <a class="header-anchor" href="#chapter-4-—-data" aria-label="Permalink to &quot;Chapter 4 — Data&quot;">​</a></h3><p>Organised around a pyramid that trades cost against fidelity, from expensive real teleoperation up to cheap but unfaithful synthetic rollouts.</p><ul><li>4.1 The data pyramid: from &quot;expensive and real&quot; to &quot;cheap and fake&quot;</li><li>4.2 Real-robot teleoperation and large-scale real datasets</li><li>4.3 Human video — the most tempting &quot;free&quot; data</li><li>4.4 Simulation and automated data generation</li><li>4.5 World models and generative data engines</li><li>4.6 Data curation, selection and scaling laws</li></ul><h3 id="chapter-5-—-methods-and-representative-systems" tabindex="-1">Chapter 5 — Methods and representative systems <a class="header-anchor" href="#chapter-5-—-methods-and-representative-systems" aria-label="Permalink to &quot;Chapter 5 — Methods and representative systems&quot;">​</a></h3><ul><li>5.1 The generalist VLA foundation-model lineage</li><li>5.2 Routes for strengthening VLA capability</li><li>5.3 Imitation-learning policy families (non-VLA specialists)</li><li>5.4 RL-enhanced VLA (RL-VLA) — one of the hottest tracks of 2025–2026</li><li>5.5 World-action models (WAM) and the &quot;should we generate the future at all&quot; debate</li><li>5.6 Navigation and mobility methods</li><li>5.7 Humanoid and whole-body methods</li><li>5.8 Efficiency and deployment: running large models on robots</li></ul><h3 id="chapter-6-—-simulators-benchmarks-and-metrics" tabindex="-1">Chapter 6 — Simulators, benchmarks and metrics <a class="header-anchor" href="#chapter-6-—-simulators-benchmarks-and-metrics" aria-label="Permalink to &quot;Chapter 6 — Simulators, benchmarks and metrics&quot;">​</a></h3><ul><li>6.1 Mainstream simulators</li><li>6.2 Manipulation benchmarks</li><li>6.3 Real-world evaluation — the most important and the most difficult</li><li>6.4 Navigation and humanoid benchmarks</li><li>6.5 World-model and embodied-reasoning benchmarks</li><li>6.6 Metrics</li></ul><h3 id="chapter-7-—-core-challenges-and-research-trends" tabindex="-1">Chapter 7 — Core challenges and research trends <a class="header-anchor" href="#chapter-7-—-core-challenges-and-research-trends" aria-label="Permalink to &quot;Chapter 7 — Core challenges and research trends&quot;">​</a></h3><ul><li>7.1 Generalisation — the number-one scientific question</li><li>7.2 The data bottleneck</li><li>7.3 Sim-to-real transfer and real-hardware reliability</li><li>7.4 Long-horizon execution and reliability</li><li>7.5 Latency and compute</li><li>7.6 Safety, alignment and robustness</li><li>7.7 Making evaluation a science</li><li>7.8 Unification and scaling — the road to general embodied intelligence</li></ul><h3 id="chapter-8-—-paper-and-resource-list-2025-06–2026-07" tabindex="-1">Chapter 8 — Paper and resource list (2025.06–2026.07) <a class="header-anchor" href="#chapter-8-—-paper-and-resource-list-2025-06–2026-07" aria-label="Permalink to &quot;Chapter 8 — Paper and resource list (2025.06–2026.07)&quot;">​</a></h3><p>Surveys with one-line guides; generalist VLA foundation models; VLA capability enhancement (3D / reasoning / memory / multimodality); RL-VLA; imitation learning and visuomotor policies; video and world models as policies (WAM); dexterous hands, humanoids and whole-body control; navigation; data, cross-embodiment and human video; simulators and benchmarks; safety; commonly used open-source repositories.</p><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/vla">Vision-Language-Action Models</a> — the same material at much greater depth on the policy side</li><li><a href="/notes/en/tutorials/video-for-embodied-ai">Video Generation for Embodied AI</a> — what video generation contributes to this stack</li><li><a href="/notes/en/tutorials/world-action-models">World-Action Models</a> — the &quot;predict in order to act&quot; family in detail</li></ul>',28)])])}const p=a(n,[["render",l]]);export{m as __pageData,p as default};
